import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

  try {
    const supabaseAdmin = createClient(
      Deno.env.get("SUPABASE_URL") ?? "",
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
    );

    const today = new Date().toISOString().split("T")[0];

    // 1. Buscar monitoramentos vencendo hoje ou amanhã
    const { data: monitoramentos, error: fetchError } = await supabaseAdmin
      .from("registros_consultor")
      .select(`
        id, 
        consultor_responsavel, 
        cliente_id, 
        talhao_id, 
        data_proxima_visita,
        objetivo_visita,
        clientes:cliente_id(nome),
        talhoes:talhao_id(nome)
      `)
      .eq("necessidade_intervencao", "monitorar")
      .eq("status", "finalizado")
      .lte("data_proxima_visita", today);

    if (fetchError) throw fetchError;

    const results = [];

    for (const mon of monitoramentos || []) {
      // Verificar se já avisamos hoje
      const { data: jaAvisado } = await supabaseAdmin
        .from("monitoramento_avisos")
        .select("id")
        .eq("registro_consultor_id", mon.id)
        .eq("tipo", "vencido")
        .gte("enviado_em", today)
        .maybeSingle();

      if (jaAvisado) continue;

      // 2. Criar notificações operacionais
      await supabaseAdmin.from("notificacoes_operacionais").insert({
        user_id: mon.consultor_responsavel,
        tipo: "alerta",
        titulo: "Monitoramento Vencido",
        mensagem: `A reavaliação do talhão ${mon.talhoes?.nome} (${mon.clientes?.nome}) venceu em ${mon.data_proxima_visita}.`,
        link: `/visita-tecnica/${mon.id}`,
        urgencia: "alta"
      });

      // 3. Atualizar alerta agronômico para risco alto
      await supabaseAdmin
        .from("alertas_agronomicos")
        .update({ nivel_risco: "alto" })
        .eq("talhao_id", mon.talhao_id)
        .eq("status", "monitoramento");

      // 4. Registrar aviso enviado
      await supabaseAdmin.from("monitoramento_avisos").insert({
        registro_consultor_id: mon.id,
        tipo: "vencido"
      });

      // 5. Enviar Push Notification
      try {
        await fetch(`${Deno.env.get("SUPABASE_URL")}/functions/v1/send-push-notification`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "Authorization": `Bearer ${Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")}`
          },
          body: JSON.stringify({
            user_ids: [mon.consultor_responsavel],
            title: "Monitoramento Vencido ⚠️",
            body: `Talhão ${mon.talhoes?.nome} aguarda reavaliação.`,
            url: `/visita-tecnica/${mon.id}`
          })
        });
      } catch (pushErr) {
        console.error("Erro ao enviar push:", pushErr);
      }

      results.push(mon.id);
    }

    return new Response(JSON.stringify({ processed: results.length }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (error) {
    return new Response(JSON.stringify({ error: error.message }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const authHeader = req.headers.get("Authorization");
    if (!authHeader?.startsWith("Bearer ")) {
      return new Response(JSON.stringify({ error: "Não autorizado" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const anonClient = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_ANON_KEY")!,
      { global: { headers: { Authorization: authHeader } } }
    );

    const token = authHeader.replace("Bearer ", "");
    const { data: claimsData, error: claimsError } = await anonClient.auth.getClaims(token);
    if (claimsError || !claimsData?.claims) {
      return new Response(JSON.stringify({ error: "Token inválido" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const callerId = claimsData.claims.sub;

    const adminClient = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
    );

    const { data: isAdmin } = await adminClient.rpc("has_role", {
      _user_id: callerId,
      _role: "administrador",
    });

    if (!isAdmin) {
      return new Response(JSON.stringify({ error: "Apenas administradores podem criar usuários" }), {
        status: 403,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const body = await req.json();
    const {
      email, password, nome, role,
      telefone, cargo, cpf_cnpj, crea, especialidade,
      cliente_id,
      cliente_ids,
      principal_cliente_id,
    } = body;

    if (!email || !password || !nome || !role) {
      return new Response(JSON.stringify({ error: "email, password, nome e role são obrigatórios" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Normaliza lista de clientes vinculados
    const finalClienteIds: string[] = Array.isArray(cliente_ids) && cliente_ids.length > 0
      ? cliente_ids
      : (cliente_id ? [cliente_id] : []);

    if (role === "cliente_produtor" && finalClienteIds.length === 0) {
      return new Response(JSON.stringify({ error: "Para perfil Produtor é obrigatório vincular pelo menos um cliente." }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const { data: userData, error: createError } = await adminClient.auth.admin.createUser({
      email,
      password,
      email_confirm: true,
      user_metadata: { nome, created_by_admin: true },
    });

    if (createError) {
      return new Response(JSON.stringify({ error: createError.message }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const userId = userData.user.id;

    const principal = principal_cliente_id && finalClienteIds.includes(principal_cliente_id)
      ? principal_cliente_id
      : finalClienteIds[0];

    // Insere vínculos N:N antes de atribuir role (trigger enforce_cliente_id_for_produtor exige)
    if (finalClienteIds.length > 0) {
      const rows = finalClienteIds.map((cid) => ({
        user_id: userId,
        cliente_id: cid,
        principal: cid === principal,
      }));
      const { error: vincErr } = await adminClient.from("user_clientes").insert(rows);
      if (vincErr) {
        return new Response(JSON.stringify({ error: "Falha ao vincular clientes: " + vincErr.message }), {
          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
    }

    await adminClient
      .from("profiles")
      .update({
        telefone, cargo, cpf_cnpj, crea, especialidade,
        cliente_id: principal ?? null,
      })
      .eq("user_id", userId);

    await adminClient.from("user_roles").delete().eq("user_id", userId);
    const { error: roleErr } = await adminClient.from("user_roles").insert({ user_id: userId, role });
    if (roleErr) {
      return new Response(JSON.stringify({ error: roleErr.message }), {
        status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    return new Response(JSON.stringify({ success: true, user_id: userId }), {
      status: 200,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (err) {
    return new Response(JSON.stringify({ error: (err as Error).message }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

// Edge Function: enviar-alertas-notificacoes
// Fase 12.6 — Envio externo de alertas críticos/alta prioridade.
// Protegida por segredo (header x-cron-secret ou Authorization Bearer).

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.45.4";
import { SMTPClient } from "https://deno.land/x/denomailer@1.6.0/mod.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-cron-secret, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

const json = (status: number, body: unknown) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });

const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SERVICE_ROLE = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const SECRET = Deno.env.get("ALERTAS_NOTIFICACOES_SECRET") ?? "";
const APP_URL =
  Deno.env.get("APP_URL") ?? Deno.env.get("SITE_URL") ?? "";

const SMTP_HOST = Deno.env.get("SMTP_HOST") ?? "";
const SMTP_PORT = Number(Deno.env.get("SMTP_PORT") ?? "587");
const SMTP_USER = Deno.env.get("SMTP_USER") ?? "";
const SMTP_PASS = Deno.env.get("SMTP_PASS") ?? "";
const SMTP_FROM = Deno.env.get("SMTP_FROM") ?? "";
const SMTP_FROM_NAME = Deno.env.get("SMTP_FROM_NAME") ?? "AR Bio";

function validarSegredo(req: Request): boolean {
  if (!SECRET) return false;
  const h = req.headers.get("x-cron-secret");
  if (h && h === SECRET) return true;
  const auth = req.headers.get("authorization") ?? "";
  if (auth.toLowerCase().startsWith("bearer ")) {
    return auth.slice(7).trim() === SECRET;
  }
  return false;
}

function smtpConfigurado(): boolean {
  return !!(SMTP_HOST && SMTP_USER && SMTP_PASS && SMTP_FROM);
}

function montarHtml(assunto: string, mensagem: string, alertaId: string): string {
  const link =
    APP_URL && APP_URL.length > 0
      ? `${APP_URL.replace(/\/$/, "")}/alertas-operacionais?alerta=${alertaId}`
      : null;
  const safe = (s: string) =>
    s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  return `<!doctype html><html><body style="font-family:Inter,Arial,sans-serif;background:#f7f7f8;padding:24px;color:#111">
  <div style="max-width:560px;margin:0 auto;background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:24px">
    <h2 style="margin:0 0 12px;font-size:18px">${safe(assunto)}</h2>
    <pre style="white-space:pre-wrap;font-family:Inter,Arial,sans-serif;font-size:14px;line-height:1.5;margin:0 0 16px">${safe(mensagem)}</pre>
    ${
      link
        ? `<a href="${link}" style="display:inline-block;background:#16a34a;color:#fff;text-decoration:none;padding:10px 16px;border-radius:8px;font-size:14px">Acessar Central de Alertas</a>`
        : ""
    }
    <p style="color:#6b7280;font-size:12px;margin-top:24px">AR Bio — notificação automática. Não responda este e-mail.</p>
  </div></body></html>`;
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
  if (req.method !== "POST") return json(405, { success: false, message: "Method not allowed" });
  if (!validarSegredo(req)) return json(401, { success: false, message: "Unauthorized" });

  const supabase = createClient(SUPABASE_URL, SERVICE_ROLE, {
    auth: { persistSession: false, autoRefreshToken: false },
  });

  let preparadas = 0;
  let enviadas = 0;
  let falhas = 0;

  try {
    // 1) Prepara fila
    const { data: prep, error: prepErr } = await supabase.rpc(
      "rpc_preparar_notificacoes_alertas",
    );
    if (prepErr) throw prepErr;
    preparadas = Number((prep as Record<string, unknown>)?.total_notificacoes_criadas ?? 0);

    // 2) Busca pendentes (apenas email; whatsapp aguarda fase futura)
    const { data: pendentes, error: pendErr } = await supabase
      .from("alertas_notificacoes")
      .select("id, alerta_id, canal, destino, assunto, mensagem")
      .eq("status", "pendente")
      .eq("canal", "email")
      .order("created_at", { ascending: true })
      .limit(50);
    if (pendErr) throw pendErr;

    if (!pendentes || pendentes.length === 0) {
      return json(200, {
        success: true,
        preparadas,
        enviadas: 0,
        falhas: 0,
        executado_em: new Date().toISOString(),
      });
    }

    if (!smtpConfigurado()) {
      // Marca todas como falhou com motivo claro (sem expor segredos)
      for (const n of pendentes) {
        await supabase.rpc("rpc_marcar_notificacao_falhou", {
          p_notificacao_id: n.id,
          p_erro: "smtp_nao_configurado",
        });
        falhas++;
      }
      return json(200, {
        success: true,
        preparadas,
        enviadas,
        falhas,
        executado_em: new Date().toISOString(),
      });
    }

    const client = new SMTPClient({
      connection: {
        hostname: SMTP_HOST,
        port: SMTP_PORT,
        tls: SMTP_PORT === 465,
        auth: { username: SMTP_USER, password: SMTP_PASS },
      },
    });

    for (const n of pendentes) {
      try {
        await client.send({
          from: `${SMTP_FROM_NAME} <${SMTP_FROM}>`,
          to: n.destino,
          subject: n.assunto ?? "Alerta AR Bio",
          content: n.mensagem,
          html: montarHtml(n.assunto ?? "Alerta AR Bio", n.mensagem, n.alerta_id),
        });
        await supabase.rpc("rpc_marcar_notificacao_enviada", {
          p_notificacao_id: n.id,
          p_provider: "smtp",
          p_provider_message_id: null,
        });
        enviadas++;
      } catch (err) {
        const msg = err instanceof Error ? err.message : "erro_envio";
        console.error("[enviar-alertas-notificacoes] envio falhou", n.id, msg);
        await supabase.rpc("rpc_marcar_notificacao_falhou", {
          p_notificacao_id: n.id,
          p_erro: msg.slice(0, 250),
        });
        falhas++;
      }
    }

    try {
      await client.close();
    } catch {
      /* noop */
    }

    return json(200, {
      success: true,
      preparadas,
      enviadas,
      falhas,
      executado_em: new Date().toISOString(),
    });
  } catch (err) {
    console.error("[enviar-alertas-notificacoes] erro geral", err);
    return json(500, {
      success: false,
      message: "Não foi possível processar notificações de alertas.",
    });
  }
});

