  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

function numberToExtenso(n: number): string {
  // Simplified PT-BR currency in words (best-effort)
  const reais = Math.floor(n);
  const cents = Math.round((n - reais) * 100);
  return `${reais.toLocaleString("pt-BR")} reais${cents ? ` e ${cents} centavos` : ""}`;
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

  try {
    const authHeader = req.headers.get("Authorization") ?? "";
    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_ANON_KEY")!,
      { global: { headers: { Authorization: authHeader } } },
    );
    const { data: userData } = await supabase.auth.getUser();
    if (!userData?.user) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } });
    }

    const { receipt_id } = await req.json();
    if (!receipt_id) throw new Error("receipt_id obrigatório");

    const { data: rec, error } = await supabase
      .from("financial_receipts")
      .select("*, clientes:customer_id(nome, razao_social), payment_methods:payment_method_id(name)")
      .eq("id", receipt_id)
      .maybeSingle();
    if (error) throw error;
    if (!rec) throw new Error("Recibo não encontrado");

    const pdf = await PDFDocument.create();
    const font = await pdf.embedFont(StandardFonts.Helvetica);
    const bold = await pdf.embedFont(StandardFonts.HelveticaBold);
    const page = pdf.addPage([595, 420]);

    page.drawRectangle({ x: 0, y: 380, width: 595, height: 40, color: rgb(0.07, 0.36, 0.2) });
    page.drawText("AR Bio On-Farm Manager", { x: 30, y: 395, size: 14, font: bold, color: rgb(1,1,1) });
    page.drawText("RECIBO DE PAGAMENTO", { x: 30, y: 350, size: 18, font: bold });
    page.drawText(`Nº ${rec.receipt_number}`, { x: 400, y: 350, size: 14, font: bold });

    const customer = (rec as any).clientes?.nome ?? (rec as any).clientes?.razao_social ?? "—";
    const method = (rec as any).payment_methods?.name ?? "—";
    const amount = Number(rec.amount);

    const lines = [
      `Recebemos de: ${customer}`,
      `A quantia de: R$ ${amount.toFixed(2).replace(".", ",")} (${numberToExtenso(amount)})`,
      `Referente a: ${rec.description ?? "Pagamento de título financeiro"}`,
      `Forma de pagamento: ${method}`,
      `Data do pagamento: ${new Date(rec.payment_date).toLocaleDateString("pt-BR")}`,
    ];
    let y = 310;
    for (const l of lines) {
      page.drawText(l, { x: 30, y, size: 11, font });
      y -= 18;
    }

    // Marca d'água CANCELADO em diagonal
    if (rec.status === "CANCELED") {
      page.drawText("CANCELADO", {
        x: 110, y: 200, size: 80, font: bold,
        color: rgb(0.85, 0.1, 0.1), opacity: 0.25, rotate: { type: "degrees", angle: 20 } as any,
      });
      if (rec.cancel_reason) {
        page.drawText(`Motivo: ${rec.cancel_reason}`, { x: 30, y: 165, size: 9, font, color: rgb(0.5,0,0) });
      }
    }

    page.drawLine({ start: { x: 30, y: 130 }, end: { x: 565, y: 130 }, thickness: 0.5, color: rgb(0.6,0.6,0.6) });
    page.drawText("Este recibo foi gerado eletronicamente pelo sistema da AR Bio.", { x: 30, y: 110, size: 9, font });
    page.drawText(`Emitido por: ${userData.user.email ?? userData.user.id}  •  ${new Date(rec.issued_at).toLocaleString("pt-BR")}`, { x: 30, y: 96, size: 8, font, color: rgb(0.3,0.3,0.3) });
    page.drawText(`Código de autenticidade: ${rec.authenticity_code}`, { x: 30, y: 78, size: 9, font: bold, color: rgb(0.07,0.36,0.2) });
    page.drawText(`Validação pública (em preparação): /verificar-recibo/${rec.public_verification_token}`, { x: 30, y: 62, size: 7, font, color: rgb(0.4,0.4,0.4) });

    const bytes = await pdf.save();
    const path = `${rec.receipt_year}/${rec.receipt_number}.pdf`;
    const { error: upErr } = await supabase.storage.from("financial-receipts").upload(path, bytes, { contentType: "application/pdf", upsert: true });
    if (upErr) throw upErr;

    await supabase.from("financial_receipts").update({ storage_bucket: "financial-receipts", storage_path: path }).eq("id", receipt_id);
    const { data: signed } = await supabase.storage.from("financial-receipts").createSignedUrl(path, 60 * 60);

    return new Response(JSON.stringify({ url: signed?.signedUrl, path, receipt_number: rec.receipt_number }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (e) {
    return new Response(JSON.stringify({ error: (e as Error).message }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.45.0";
import { PDFDocument, StandardFonts, rgb } from "https://esm.sh/pdf-lib@1.17.1";
import * as XLSX from "https://esm.sh/xlsx@0.18.5";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

interface Body {
  report_type: string;
  filters: Record<string, unknown>;
  format: "PDF" | "XLSX" | "CSV";
  title?: string;
}

const RPC_MAP: Record<string, string> = {
  monthly: "get_report_monthly_financial",
  receivables: "get_report_receivables",
  payables: "get_report_payables",
  delinquency: "get_report_delinquency",
  nfe_pending: "get_report_nfe_pending",
  deliveries_billing: "get_report_deliveries_billing_status",
  customer_statement: "get_report_customer_statement",
  accountability: "get_report_accountability",
  cashflow: "get_financial_cashflow",
  dre: "get_financial_dre_summary",
};

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

  try {
    const authHeader = req.headers.get("Authorization") ?? "";
    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_ANON_KEY")!,
      { global: { headers: { Authorization: authHeader } } },
    );
    const { data: userData } = await supabase.auth.getUser();
    if (!userData?.user) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } });
    }

    const body = (await req.json()) as Body;
    const rpcName = RPC_MAP[body.report_type];
    if (!rpcName) throw new Error(`Tipo de relatório inválido: ${body.report_type}`);

    // Call the RPC with filters as params
    const { data, error } = await supabase.rpc(rpcName, body.filters as never);
    if (error) throw error;

    const rows: Array<Record<string, unknown>> = Array.isArray(data)
      ? data
      : data && typeof data === "object"
        ? [data as Record<string, unknown>]
        : [];

    const title = body.title ?? body.report_type;
    const ts = new Date().toISOString().replace(/[:.]/g, "-");
    const filename = `${body.report_type}_${ts}.${body.format.toLowerCase()}`;
    let fileBytes: Uint8Array;
    let contentType: string;

    if (body.format === "PDF") {
      const pdf = await PDFDocument.create();
      const font = await pdf.embedFont(StandardFonts.Helvetica);
      const bold = await pdf.embedFont(StandardFonts.HelveticaBold);
      const page = pdf.addPage([595, 842]);
      page.drawText("AR Bio On-Farm Manager", { x: 40, y: 800, size: 14, font: bold, color: rgb(0.1,0.4,0.2) });
      page.drawText(title, { x: 40, y: 780, size: 18, font: bold });
      page.drawText(`Gerado em ${new Date().toLocaleString("pt-BR")}`, { x: 40, y: 762, size: 9, font });
      page.drawText(`Filtros: ${JSON.stringify(body.filters)}`, { x: 40, y: 748, size: 8, font, color: rgb(0.3,0.3,0.3) });
      let y = 720;
      if (rows.length > 0) {
        const cols = Object.keys(rows[0]);
        page.drawText(cols.join(" | "), { x: 40, y, size: 8, font: bold });
        y -= 14;
        for (const row of rows.slice(0, 60)) {
          const line = cols.map((c) => String(row[c] ?? "")).join(" | ");
          page.drawText(line.substring(0, 110), { x: 40, y, size: 7, font });
          y -= 12;
          if (y < 50) break;
        }
      } else {
        page.drawText("Nenhum dado encontrado.", { x: 40, y, size: 10, font });
      }
      page.drawText(`AR Bio • ${rows.length} registro(s)`, { x: 40, y: 30, size: 8, font, color: rgb(0.4,0.4,0.4) });
      fileBytes = await pdf.save();
      contentType = "application/pdf";
    } else if (body.format === "XLSX") {
      const ws = XLSX.utils.json_to_sheet(rows.length ? rows : [{ info: "Nenhum dado" }]);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, title.substring(0, 28));
      fileBytes = new Uint8Array(XLSX.write(wb, { type: "array", bookType: "xlsx" }));
      contentType = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
    } else {
      const cols = rows.length ? Object.keys(rows[0]) : [];
      const csv = [cols.join(","), ...rows.map((r) => cols.map((c) => JSON.stringify(r[c] ?? "")).join(","))].join("\n");
      fileBytes = new TextEncoder().encode(csv);
      contentType = "text/csv";
    }

    const path = `${userData.user.id}/${filename}`;
    const { error: upErr } = await supabase.storage.from("financial-reports").upload(path, fileBytes, { contentType, upsert: true });
    if (upErr) throw upErr;

    await supabase.rpc("register_financial_report_export", {
      p_report_type: body.report_type,
      p_report_title: title,
      p_filters: body.filters as any,
      p_file_format: body.format,
      p_storage_path: path,
      p_status: "SUCCESS",
      p_error_message: null,
    });

    const { data: signed } = await supabase.storage.from("financial-reports").createSignedUrl(path, 60 * 60);

    return new Response(JSON.stringify({ url: signed?.signedUrl, path, row_count: rows.length }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (e) {
    return new Response(JSON.stringify({ error: (e as Error).message }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

// Edge Function: gerar-alertas-operacionais
// Executa o motor de geracao de alertas operacionais via service role.
// Protegida por segredo (ALERTAS_CRON_SECRET) — destinada a cron/agendadores.
//
// Aceita header `x-cron-secret` OU `Authorization: Bearer <ALERTAS_CRON_SECRET>`.
// Nao expoe stack trace na resposta publica.

import { createClient } from "npm:@supabase/supabase-js@2";

const corsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-cron-secret",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

function jsonResponse(status: number, body: Record<string, unknown>) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }
  if (req.method !== "POST") {
    return jsonResponse(405, { success: false, message: "Metodo nao permitido." });
  }

  const expected = Deno.env.get("ALERTAS_CRON_SECRET");
  if (!expected) {
    console.error("[gerar-alertas-operacionais] ALERTAS_CRON_SECRET nao configurado");
    return jsonResponse(500, {
      success: false,
      message: "Servico indisponivel.",
    });
  }

  const headerSecret = req.headers.get("x-cron-secret");
  const authHeader = req.headers.get("authorization") ?? "";
  const bearer = authHeader.toLowerCase().startsWith("bearer ")
    ? authHeader.slice(7).trim()
    : "";
  const provided = headerSecret || bearer;

  if (!provided || provided !== expected) {
    return jsonResponse(401, { success: false, message: "Nao autorizado." });
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL");
  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!supabaseUrl || !serviceKey) {
    console.error("[gerar-alertas-operacionais] Variaveis de ambiente ausentes");
    return jsonResponse(500, {
      success: false,
      message: "Servico indisponivel.",
    });
  }

  let body: { tipo_execucao?: string; origem?: string } = {};
  try {
    if (req.headers.get("content-type")?.includes("application/json")) {
      body = await req.json();
    }
  } catch {
    body = {};
  }

  const tipo = typeof body.tipo_execucao === "string" ? body.tipo_execucao : "edge_function";
  const origem = typeof body.origem === "string" ? body.origem : "cron";

  const supabase = createClient(supabaseUrl, serviceKey, {
    auth: { persistSession: false, autoRefreshToken: false },
  });

  try {
    const { data, error } = await supabase.rpc("rpc_executar_motor_alertas", {
      p_tipo_execucao: tipo,
      p_origem: origem,
    });

    if (error) {
      console.error("[gerar-alertas-operacionais] erro RPC:", error.message);
      return jsonResponse(500, {
        success: false,
        message: "Nao foi possivel executar o motor de alertas.",
      });
    }

    return jsonResponse(200, {
      success: true,
      executado_em: new Date().toISOString(),
      resultado: data ?? {},
    });
  } catch (err) {
    console.error("[gerar-alertas-operacionais] excecao:", err);
    return jsonResponse(500, {
      success: false,
      message: "Nao foi possivel executar o motor de alertas.",
    });
  }
});

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const authHeader = req.headers.get("Authorization");
    if (!authHeader?.startsWith("Bearer ")) {
      return new Response(JSON.stringify({ error: "Não autorizado" }), {
        status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const anonClient = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_ANON_KEY")!,
      { global: { headers: { Authorization: authHeader } } }
    );
    const token = authHeader.replace("Bearer ", "");
    const { data: claimsData, error: claimsError } = await anonClient.auth.getClaims(token);
    if (claimsError || !claimsData?.claims) {
      return new Response(JSON.stringify({ error: "Token inválido" }), {
        status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }
    const callerId = claimsData.claims.sub;

    const admin = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
    );

    const roles = ["administrador", "gestor", "administrativo"];
    let allowed = false;
    for (const r of roles) {
      const { data } = await admin.rpc("has_role", { _user_id: callerId, _role: r });
      if (data) { allowed = true; break; }
    }
    if (!allowed) {
      return new Response(JSON.stringify({ error: "Sem permissão" }), {
        status: 403, headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const { cliente_id } = await req.json();
    if (!cliente_id) {
      return new Response(JSON.stringify({ error: "cliente_id é obrigatório" }), {
        status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Busca vínculos via tabela N:N
    const { data: vinculos, error: vErr } = await admin
      .from("user_clientes")
      .select("user_id, principal")
      .eq("cliente_id", cliente_id);
    if (vErr) throw vErr;

    const userIds = (vinculos ?? []).map((v: any) => v.user_id);
    if (userIds.length === 0) {
      return new Response(JSON.stringify({ users: [] }), {
        status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const principalMap = new Map<string, boolean>(
      (vinculos ?? []).map((v: any) => [v.user_id, !!v.principal])
    );

    const [{ data: profiles }, { data: rolesRows }] = await Promise.all([
      admin.from("profiles").select("id, user_id, nome, email, telefone, ativo, created_at").in("user_id", userIds),
      admin.from("user_roles").select("user_id, role").in("user_id", userIds),
    ]);

    const rolesByUser = new Map<string, string[]>();
    for (const r of rolesRows ?? []) {
      const arr = rolesByUser.get((r as any).user_id) ?? [];
      arr.push((r as any).role);
      rolesByUser.set((r as any).user_id, arr);
    }

    const enriched = await Promise.all((profiles ?? []).map(async (p: any) => {
      let last_sign_in_at: string | null = null;
      try {
        const { data: u } = await admin.auth.admin.getUserById(p.user_id);
        last_sign_in_at = u?.user?.last_sign_in_at ?? null;
      } catch { /* ignore */ }
      return {
        ...p,
        principal: principalMap.get(p.user_id) ?? false,
        roles: rolesByUser.get(p.user_id) ?? [],
        last_sign_in_at,
      };
    }));

    // Principal primeiro
    enriched.sort((a, b) => (a.principal === b.principal ? 0 : a.principal ? -1 : 1));

    return new Response(JSON.stringify({ users: enriched }), {
      status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (err) {
    return new Response(JSON.stringify({ error: (err as Error).message }), {
      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import webpush from "https://esm.sh/web-push@3.6.6";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

  try {
    const { user_ids, title, body, url, tag } = await req.json();

    const supabaseAdmin = createClient(
      Deno.env.get("SUPABASE_URL") ?? "",
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
    );

    // Buscar assinaturas
    const { data: subs, error: subError } = await supabaseAdmin
      .from("push_subscriptions")
      .select("*")
      .in("user_id", user_ids);

    if (subError) throw subError;

    const vapidPublic = Deno.env.get("VAPID_PUBLIC_KEY");
    const vapidPrivate = Deno.env.get("VAPID_PRIVATE_KEY");
    const vapidSubject = Deno.env.get("VAPID_SUBJECT") || "mailto:contato@ar-bio.com";

    if (!vapidPublic || !vapidPrivate) {
      throw new Error("VAPID keys not configured");
    }

    webpush.setVapidDetails(vapidSubject, vapidPublic, vapidPrivate);

    const payload = JSON.stringify({
      title,
      body,
      url: url || "/app",
      tag: tag || "default"
    });

    const results = await Promise.all(
      subs.map(async (sub) => {
        try {
          const pushSubscription = {
            endpoint: sub.endpoint,
            keys: {
              p256dh: sub.p256dh,
              auth: sub.auth
            }
          };
          await webpush.sendNotification(pushSubscription, payload);

          await supabaseAdmin
            .from("push_subscriptions")
            .update({ last_used_at: new Date().toISOString() })
            .eq("id", sub.id);

          return { id: sub.id, success: true };
        } catch (err) {
          if (err.statusCode === 410 || err.statusCode === 404) {
            // Assinatura expirada ou inválida
            await supabaseAdmin.from("push_subscriptions").delete().eq("id", sub.id);
          }
          return { id: sub.id, success: false, error: err.message };
        }
      })
    );

    return new Response(JSON.stringify({ results }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (error) {
    return new Response(JSON.stringify({ error: error.message }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.38.4";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const GOOGLE_GATEWAY = "https://connector-gateway.lovable.dev/google_calendar/calendar/v3";

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

  try {
    const { solicitacaoId, action } = await req.json();

    const supabase = createClient(
      Deno.env.get("VITE_SUPABASE_URL") ?? "",
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
    );

    // 1. Buscar dados da solicitação
    const { data: sol, error: solError } = await supabase
      .from("portal_solicitacoes")
      .select("*, clientes(nome), fazendas(nome), talhoes(nome)")
      .eq("id", solicitacaoId)
      .single();

    if (solError || !sol) throw new Error("Solicitação não encontrada");

    const LOVABLE_API_KEY = Deno.env.get("LOVABLE_API_KEY");
    const GOOGLE_MAIL_API_KEY = Deno.env.get("GOOGLE_MAIL_API_KEY");

    if (!LOVABLE_API_KEY || !GOOGLE_MAIL_API_KEY) {
      console.log("Calendar Sync: Credentials missing, skipping sync.");
      return new Response(JSON.stringify({ skipped: true, reason: "Credentials not configured" }), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const eventData = {
      summary: `Visita A.R Bio: ${sol.clientes?.nome || "Cliente"}`,
      description: `
        Fazenda: ${sol.fazendas?.nome || "—"}
        Talhão: ${sol.talhoes?.nome || "—"}
        Demanda: ${sol.tipo_demanda}
        Descrição: ${sol.descricao || "—"}
        Link: ${Deno.env.get("VITE_SUPABASE_URL")?.replace(".supabase.co", ".lovable.app")}/agenda-tecnica?id=${sol.id}
      `.trim(),
      start: {
        dateTime: sol.data_prevista_atendimento,
        timeZone: "America/Sao_Paulo",
      },
      end: {
        dateTime: new Date(new Date(sol.data_prevista_atendimento).getTime() + 2 * 60 * 60 * 1000).toISOString(),
        timeZone: "America/Sao_Paulo",
      },
    };

    let response;
    if (action === "delete" && sol.external_event_id) {
      response = await fetch(`${GOOGLE_GATEWAY}/calendars/primary/events/${sol.external_event_id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${LOVABLE_API_KEY}`,
          "X-Connection-Api-Key": GOOGLE_MAIL_API_KEY,
        },
      });
    } else if (sol.external_event_id) {
      response = await fetch(`${GOOGLE_GATEWAY}/calendars/primary/events/${sol.external_event_id}`, {
        method: "PUT",
        headers: {
          Authorization: `Bearer ${LOVABLE_API_KEY}`,
          "X-Connection-Api-Key": GOOGLE_MAIL_API_KEY,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(eventData),
      });
    } else {
      response = await fetch(`${GOOGLE_GATEWAY}/calendars/primary/events`, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${LOVABLE_API_KEY}`,
          "X-Connection-Api-Key": GOOGLE_MAIL_API_KEY,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(eventData),
      });
    }

    let result;
    try {
      result = response.status === 204 ? {} : await response.json();
    } catch (e) {
      result = { error: "Failed to parse response", details: await response.text() };
    }

    if (response.ok) {
      if (result.id || action === "delete") {
        if (result.id) {
          await supabase.from("portal_solicitacoes").update({ external_event_id: result.id }).eq("id", sol.id);
        }
        await supabase.from("agenda_sync_log").insert({
          solicitacao_id: sol.id,
          provider: "google",
          external_event_id: result.id || sol.external_event_id,
          status: "synced",
          last_synced_at: new Date().toISOString()
        });
      }
    } else {
       await supabase.from("agenda_sync_log").insert({
          solicitacao_id: sol.id,
          provider: "google",
          status: "failed",
          error_message: typeof result === 'string' ? result : JSON.stringify(result)
        });
    }

    return new Response(JSON.stringify(result), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (error) {
    return new Response(JSON.stringify({ error: error.message }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
      status: 400,
    });
  }
});

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const { fazenda_id } = await req.json();
    if (!fazenda_id) {
      return new Response(JSON.stringify({ error: "fazenda_id é obrigatório" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, supabaseKey);

    // Get farm coordinates
    const { data: fazenda, error: fazendaError } = await supabase
      .from("fazendas")
      .select("id, nome, latitude, longitude")
      .eq("id", fazenda_id)
      .single();

    if (fazendaError || !fazenda) {
      return new Response(JSON.stringify({ error: "Fazenda não encontrada" }), {
        status: 404,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    if (!fazenda.latitude || !fazenda.longitude) {
      return new Response(
        JSON.stringify({ error: "Fazenda sem coordenadas cadastradas. Atualize latitude e longitude da fazenda." }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const lat = fazenda.latitude;
    const lon = fazenda.longitude;

    // Fetch last 7 days weather from Open-Meteo
    const endDate = new Date().toISOString().split("T")[0];
    const startDate = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split("T")[0];

    const apiUrl = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&daily=temperature_2m_max,temperature_2m_min,temperature_2m_mean,relative_humidity_2m_mean,precipitation_sum,wind_speed_10m_max,shortwave_radiation_sum&start_date=${startDate}&end_date=${endDate}&timezone=America/Sao_Paulo`;

    const weatherRes = await fetch(apiUrl);
    if (!weatherRes.ok) {
      const errText = await weatherRes.text();
      return new Response(
        JSON.stringify({ error: `Erro na API Open-Meteo: ${weatherRes.status} - ${errText}` }),
        { status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const weather = await weatherRes.json();
    const daily = weather.daily;

    if (!daily || !daily.time || !daily.time.length) {
      return new Response(JSON.stringify({ error: "Sem dados climáticos disponíveis para estas coordenadas" }), {
        status: 404,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Build records to insert
    const records = daily.time.map((date: string, i: number) => ({
      fazenda_id,
      data_hora: `${date}T12:00:00-03:00`,
      temperatura: daily.temperature_2m_mean?.[i] ?? null,
      umidade: daily.relative_humidity_2m_mean?.[i] ?? null,
      chuva_mm: daily.precipitation_sum?.[i] ?? 0,
      vento_kmh: daily.wind_speed_10m_max?.[i] ?? null,
      radiacao_solar: daily.shortwave_radiation_sum?.[i] ?? null,
    }));

    // Delete existing data for same period to avoid duplicates
    await supabase
      .from("clima_dados")
      .delete()
      .eq("fazenda_id", fazenda_id)
      .gte("data_hora", `${startDate}T00:00:00`)
      .lte("data_hora", `${endDate}T23:59:59`);

    // Insert new records
    const { error: insertError } = await supabase.from("clima_dados").insert(records);

    if (insertError) {
      return new Response(JSON.stringify({ error: `Erro ao salvar dados: ${insertError.message}` }), {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    return new Response(
      JSON.stringify({
        success: true,
        fazenda: fazenda.nome,
        registros: records.length,
        periodo: `${startDate} a ${endDate}`,
      }),
      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (err) {
    const msg = err instanceof Error ? err.message : "Erro desconhecido";
    return new Response(JSON.stringify({ error: msg }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});
